import { createRequire } from "node:module";

import { orsoGlob } from "../../integrations/orso/index.js";

const require = createRequire(import.meta.url);
const getZod = () => require("astro/zod").z;

/*
 * The site's content models: one Astro collection per folder under `src/content/`, each loaded
 * with `orsoGlob` so Orso can edit its entries. This file belongs to the site; edit it to add a
 * collection or change a field. `astro.config.mjs` passes `collections` to
 * `orso({ collections })`, and `src/content.config.ts` re-exports them from
 * `virtual:orso/collections`.
 */

/** @param {{ loader: unknown, schema: unknown }} config */
function contentCollection(config) {
  return { ...config, type: "content_layer" };
}

/** Sample posts for the starter — delete or replace when you define your own models. */
const posts = contentCollection({
  loader: orsoGlob({ base: "./src/content/posts", pattern: "*.md" }),
  schema: () => {
    const z = getZod();
    return z.object({
      title: z.string(),
      date: z
        .string()
        .regex(/^\d{4}-\d{2}-\d{2}$/, "Use YYYY-MM-DD")
        .refine(
          (value) => {
            const date = new Date(`${value}T00:00:00Z`);
            return Number.isFinite(date.getTime()) && date.toISOString().slice(0, 10) === value;
          },
          "Use a valid calendar date",
        )
        .meta({ editor: { type: "date", knownRefinement: true } }),
    });
  },
});

/**
 * `orso({ collections })` entries, in sidebar order. `previewPath` is the page an entry is shown
 * on (`slug` is the entry id, the Markdown filename without extension).
 */
export const collections = {
  posts: { collection: posts, previewPath: ({ slug }) => `/posts/${slug}/` },
};

import assert from "node:assert/strict";
import { test } from "node:test";
import { spawnSync } from "node:child_process";
import { cpSync, existsSync, mkdtempSync, readFileSync, rmSync, symlinkSync } from "node:fs";
import { tmpdir } from "node:os";
import { join, resolve } from "node:path";

const root = resolve(import.meta.dirname, "..");

test("astro sync writes the orso content manifest", () => {
  const dir = mkdtempSync(join(tmpdir(), "orso-manifest-"));
  try {
    for (const path of ["src", "public", "integrations", "astro.config.mjs", "package.json"]) {
      cpSync(join(root, path), join(dir, path), { recursive: true });
    }
    symlinkSync(join(root, "node_modules"), join(dir, "node_modules"), "dir");
    const result = spawnSync(process.execPath, [join(root, "node_modules/astro/bin/astro.mjs"), "sync"], {
      cwd: dir,
      encoding: "utf8",
      env: process.env,
    });
    assert.equal(result.status, 0, result.stdout + result.stderr);

    const path = join(dir, ".astro/orso-content.json");
    assert.ok(existsSync(path), `missing ${path}\n${result.stdout}${result.stderr}`);
    const manifest = JSON.parse(readFileSync(path, "utf8"));
    assert.equal(manifest.version, 1);
    assert.deepEqual(
      manifest.collections.map(({ name }) => name),
      ["posts"],
    );
    const byName = Object.fromEntries(manifest.collections.map((collection) => [collection.name, collection]));
    assert.deepEqual(byName.posts.loader, { base: "src/content/posts", pattern: "*.md" });
    for (const collection of manifest.collections) {
      assert.equal(collection.supportedForEditing, true, collection.reason);
    }
    assert.equal(byName.posts.fields.properties.date.type, "date");
    assert.equal(byName.posts.fields.properties.title.type, "string");
  } finally {
    rmSync(dir, { recursive: true, force: true });
  }
});

import { getCollection, type CollectionEntry } from "astro:content";

export type Post = CollectionEntry<"posts">;

/** All posts, newest `date` first. */
export async function loadPosts(): Promise<Post[]> {
  const posts = await getCollection("posts");
  return posts.sort((a, b) => b.data.date.localeCompare(a.data.date));
}

/** Format a YYYY-MM-DD date for display. */
export function formatDate(value: string): string {
  const date = new Date(`${value}T00:00:00Z`);
  return date.toLocaleDateString("en-US", { year: "numeric", month: "long", day: "numeric", timeZone: "UTC" });
}

import { loadPosts } from "./posts";

export interface SitePage {
  /** Site path, e.g. `/posts/hello-orso/`. */
  path: string;
  /** Last change (YYYY-MM-DD), when known. */
  lastmod?: string;
}

/**
 * Paths of the static `.astro` pages in src/pages (no `[param]` routes, no `_` files, no 404),
 * so a page you add shows up in the sitemap without editing this file.
 */
const staticPaths = () =>
  Object.keys(import.meta.glob("../pages/**/*.astro"))
    .map((file) => file.replace(/^\.\.\/pages/, "").replace(/\.astro$/, ""))
    .filter((route) => !/\[|\/_|^\/404$/.test(route))
    .map((route) => route.replace(/\/index$/, "/").replace(/([^/])$/, "$1/"));

/** Every page of the built site: static pages and sample posts. */
export async function sitePages(): Promise<SitePage[]> {
  const posts = await loadPosts();
  const pages: SitePage[] = [
    ...staticPaths().map((path) => ({ path })),
    ...posts.map((post) => ({ path: `/posts/${post.id}/`, lastmod: post.data.date })),
  ];
  const seen = new Set<string>();
  return pages
    .filter((page) => !seen.has(page.path) && seen.add(page.path))
    .sort((a, b) => (a.path === "/" ? -1 : b.path === "/" ? 1 : a.path.localeCompare(b.path)));
}

---
import PageHeader from "../../components/PageHeader.astro";
import Base from "../../layouts/Base.astro";
import { formatDate, loadPosts } from "../../lib/posts";
import { site } from "../../site";

const posts = await loadPosts();
---

<Base title="Sample posts" description="Example content from the starter posts collection.">
  <PageHeader
    title="Sample posts"
    description="These entries come from src/content/posts/. Edit them in Orso or replace the collection with your own model."
    back={{ label: "Back home", href: "/" }}
  />
  <div class="page mt-12 pb-section">
    {posts.length === 0 ? (
      <p class="text-muted">
        No posts yet. Add a Markdown file under <code class="text-ink">src/content/posts/</code> or read the{" "}
        <a class="link" href={site.docsUrl} rel="noopener noreferrer">docs</a>.
      </p>
    ) : (
      <ul class="divide-y divide-line border-y border-line">
        {posts.map((post) => (
          <li class="py-6">
            <a class="group block" href={`/posts/${post.id}/`}>
              <time class="label" datetime={post.data.date}>{formatDate(post.data.date)}</time>
              <h2 class="mt-2 text-2xl font-light tracking-display text-ink transition-colors duration-quick ease-gentle group-hover:text-accent">
                {post.data.title}
              </h2>
            </a>
          </li>
        ))}
      </ul>
    )}
  </div>
</Base>

---
import { render } from "astro:content";
import Base from "../../layouts/Base.astro";
import { formatDate, loadPosts } from "../../lib/posts";
import { absoluteUrl, breadcrumbs } from "../../lib/seo";

export async function getStaticPaths() {
  const posts = await loadPosts();
  return posts.map((entry) => ({ params: { slug: entry.id }, props: { entry } }));
}

const { entry } = Astro.props;
const { Content } = await render(entry);
const path = `/posts/${entry.id}/`;
const jsonLd = [
  {
    "@context": "https://schema.org",
    "@type": "BlogPosting",
    headline: entry.data.title,
    datePublished: entry.data.date,
    url: absoluteUrl(path),
    mainEntityOfPage: absoluteUrl(path),
  },
  breadcrumbs([
    { name: "Home", path: "/" },
    { name: "Sample posts", path: "/posts/" },
    { name: entry.data.title, path },
  ]),
];
---

<Base title={entry.data.title} type="article" published={entry.data.date} jsonLd={jsonLd}>
  <article class="page pt-14 pb-section md:pt-20">
    <div class="mx-auto max-w-prose">
      <a class="link text-sm text-muted" href="/posts/">Back to sample posts</a>
      <time class="label rise mt-10 block" datetime={entry.data.date}>{formatDate(entry.data.date)}</time>
      <h1 class="rise mt-4 text-4xl font-light tracking-display text-ink md:text-5xl">{entry.data.title}</h1>
      <div class="prose mt-12 max-w-none border-t border-line pt-10 prose-img:h-auto prose-img:max-w-full prose-img:rounded-md">
        <Content />
      </div>
    </div>
  </article>
</Base>

/** Site-wide name, description, navigation and footer, rendered by `layouts/Base.astro`. */
export const site = {
  name: "Starter",
  /** Short promise, used after the name in the home page title. */
  tagline: "Your Astro site, editable in Orso",
  /** Default meta description and social card text (keep it under 160 characters). */
  description:
    "A thin Astro starter with a get-started home and one sample posts collection you can edit in Orso.",
  /** Placeholder live address. The build uses PUBLIC_SITE_URL when it is set; replace this with your domain. */
  url: "https://example.com",
  /** Product / docs entry for Learn and Read the docs CTAs. */
  docsUrl: "https://projectorso.cc",
  /** Default social card, served from `public/`. */
  ogImage: "/og-default.png",
  nav: [{ label: "Examples", href: "/posts/" }],
  /** Header call to action; set to `null` to hide it. */
  cta: { label: "View sample posts", href: "/posts/" },
  footer: {
    text: "Scaffolded with Orso. Replace this copy with your own.",
    links: [
      { label: "Learn", href: "https://projectorso.cc" },
      { label: "Examples", href: "/posts/" },
      { label: "Orso", href: "https://projectorso.cc" },
    ],
  },
  socials: [] as { label: string; href: string }[],
};

---
import { Font } from "astro:assets";
import { ClientRouter } from "astro:transitions";
import Wordmark from "../components/Wordmark.astro";
import { absoluteUrl, themeColors } from "../lib/seo";
import { site } from "../site";
import "../styles/global.css";

interface Props {
  /** Page title; " | Starter" is appended. Omit on the home page to get "Starter | tagline". */
  title?: string;
  /** Meta description; defaults to `site.description`. */
  description?: string;
  /** Social card image (a `public/` path or absolute URL); defaults to `site.ogImage`. */
  image?: string;
  /** Alt text for the social card image. */
  imageAlt?: string;
  /** `article` for posts, `website` otherwise. */
  type?: "website" | "article";
  /** schema.org objects, each rendered as its own JSON-LD block. Defaults to a WebPage. */
  jsonLd?: Record<string, unknown>[];
  /** Article dates (YYYY-MM-DD) for Open Graph. */
  published?: string;
  /** Keep the page out of search results. */
  noindex?: boolean;
}
const {
  title,
  description = site.description,
  image = site.ogImage,
  imageAlt = `${site.name}: ${site.tagline}`,
  type = "website",
  published,
  noindex = false,
} = Astro.props;
const fullTitle = title ? `${title} | ${site.name}` : `${site.name} | ${site.tagline}`;
const canonical = new URL(Astro.url.pathname, Astro.site ?? site.url).href;
const ogImage = absoluteUrl(image);
const jsonLd = Astro.props.jsonLd ?? [
  { "@context": "https://schema.org", "@type": "WebPage", name: title ?? site.name, description, url: canonical },
];
const here = Astro.url.pathname;
const isCurrent = (link: string) => link.startsWith("/") && link !== "/" && here.startsWith(link);
const external = (link: string) => /^https?:\/\//.test(link);
---

<html lang="en">
  <head>
    <meta charset="utf-8" />
    <meta name="viewport" content="width=device-width, initial-scale=1" />
    <title>{fullTitle}</title>
    <meta name="description" content={description} />
    <link rel="canonical" href={canonical} />
    {noindex && <meta name="robots" content="noindex" />}
    <meta property="og:type" content={type} />
    <meta property="og:site_name" content={site.name} />
    <meta property="og:title" content={title ?? fullTitle} />
    <meta property="og:description" content={description} />
    <meta property="og:url" content={canonical} />
    <meta property="og:image" content={ogImage} />
    {image === site.ogImage && <meta property="og:image:width" content="1200" />}
    {image === site.ogImage && <meta property="og:image:height" content="630" />}
    <meta property="og:image:alt" content={imageAlt} />
    {published && <meta property="article:published_time" content={published} />}
    <meta name="twitter:card" content="summary_large_image" />
    <meta name="twitter:title" content={title ?? fullTitle} />
    <meta name="twitter:description" content={description} />
    <meta name="twitter:image" content={ogImage} />
    <meta name="theme-color" media="(prefers-color-scheme: light)" content={themeColors.light} />
    <meta name="theme-color" media="(prefers-color-scheme: dark)" content={themeColors.dark} />
    <link rel="icon" href="/favicon.svg" type="image/svg+xml" />
    <link rel="apple-touch-icon" href="/apple-touch-icon.png" />
    <link rel="sitemap" href="/sitemap.xml" />
    <Font cssVariable="--font-albert-sans" preload={[{ style: "normal" }]} />
    {jsonLd.map((data) => <script type="application/ld+json" is:inline set:html={JSON.stringify(data).replace(/</g, "\\u003c")} />)}
    <ClientRouter fallback="swap" />
  </head>
  <body class="flex min-h-dvh flex-col bg-surface font-sans text-ink antialiased">
    <a
      class="sr-only rounded-md bg-accent px-4 py-2 text-on-accent focus:not-sr-only focus:fixed focus:top-4 focus:left-4 focus:z-50"
      href="#main">Skip to content</a
    >
    <header class="sticky top-0 z-40 border-b border-line bg-surface/90 backdrop-blur-md" transition:animate="none">
      <div class="page flex min-h-header flex-wrap items-center gap-x-10 gap-y-1 py-3 md:flex-nowrap">
        <a class="-m-1 rounded-sm p-1" href="/" aria-label={`${site.name} home`}><Wordmark /></a>
        <nav class="order-last -mx-2 flex w-full gap-1 overflow-x-auto md:order-none md:w-auto" aria-label="Main">
          {site.nav.map((link) => (
            <a
              class="shrink-0 rounded-sm px-2 py-1 text-sm text-muted transition-colors duration-quick ease-gentle hover:text-ink aria-[current=page]:text-ink"
              href={link.href}
              aria-current={isCurrent(link.href) ? "page" : undefined}
              rel={external(link.href) ? "noopener noreferrer" : undefined}>{link.label}</a
            >
          ))}
        </nav>
        {site.cta && (
          <a
            class="ml-auto shrink-0 rounded-full bg-accent px-4 py-1.5 text-sm font-medium text-on-accent transition-colors duration-quick ease-gentle hover:bg-accent-hover"
            href={site.cta.href}
            rel={external(site.cta.href) ? "noopener noreferrer" : undefined}>{site.cta.label}</a
          >
        )}
      </div>
    </header>

    <main id="main" class="flex flex-1 flex-col"><slot /></main>

    <footer class="mt-auto border-t border-line">
      <div class="page flex flex-wrap items-center justify-between gap-4 py-8">
        <p class="text-xs text-muted">{site.footer.text}</p>
        <nav class="flex flex-wrap gap-x-6 gap-y-2 text-sm" aria-label="Footer">
          {site.footer.links.map((link) => (
            <a
              class="text-muted transition-colors duration-quick ease-gentle hover:text-ink"
              href={link.href}
              rel={external(link.href) ? "noopener noreferrer" : undefined}>{link.label}</a
            >
          ))}
        </nav>
      </div>
    </footer>
  </body>
</html>

import assert from "node:assert/strict";
import { test } from "node:test";
import { spawnSync } from "node:child_process";
import { cpSync, existsSync, mkdtempSync, mkdirSync, readFileSync, rmSync, symlinkSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join, resolve } from "node:path";

const root = resolve(import.meta.dirname, "..");
const html = (dir, path) => readFileSync(join(dir, "dist", path, "index.html"), "utf8");
function fixture(run) {
  const dir = mkdtempSync(join(tmpdir(), "content-pages-"));
  try {
    for (const path of ["src", "public", "integrations", "astro.config.mjs", "package.json"]) {
      cpSync(join(root, path), join(dir, path), { recursive: true });
    }
    symlinkSync(join(root, "node_modules"), join(dir, "node_modules"), "dir");
    run(dir);
  } finally {
    rmSync(dir, { recursive: true, force: true });
  }
}
function build(dir) {
  const result = spawnSync(process.execPath, [join(root, "node_modules/astro/bin/astro.mjs"), "build"], {
    cwd: dir,
    encoding: "utf8",
    env: process.env,
  });
  assert.equal(result.status, 0, result.stdout + result.stderr);
}

test("built get-started home and sample posts render", () => {
  const home = html(root, "");
  assert.match(home, /View sample posts/);
  assert.match(home, /href="\/posts\/"/);
  assert.match(home, /href="https:\/\/projectorso\.cc"/);
  assert.match(home, /Get started by editing src\/pages\/index\.astro/);
  assert.doesNotMatch(home, /id="hero"/);
  assert.doesNotMatch(home, /id="pricing"/);
  assert.match(html(root, "posts"), /Hello from Orso/);
  assert.match(html(root, "posts"), /Add your own content/);
  assert.match(html(root, "posts/hello-orso"), /sample post/);
  assert.equal(existsSync(join(root, "dist/blog")), false);
  assert.equal(existsSync(join(root, "dist/help")), false);
});

test("built routes sort posts by date and handle an empty collection", () =>
  fixture((dir) => {
    mkdirSync(join(dir, "src/content/posts"), { recursive: true });
    writeFileSync(
      join(dir, "src/content/posts/a-new.md"),
      '---\ntitle: Newest article\ndate: "2026-10-11"\n---\nNew **body**',
    );
    writeFileSync(
      join(dir, "src/content/posts/z-old.md"),
      '---\ntitle: Oldest article\ndate: "2020-01-01"\n---\nOld body',
    );
    build(dir);
    const list = html(dir, "posts");
    assert.ok(list.indexOf("Newest article") < list.indexOf("Oldest article"));
    assert.match(list, /href="\/posts\/a-new\/"/);
    assert.match(html(dir, "posts/a-new"), /<strong>body<\/strong>/);

    const file = (path) => readFileSync(join(dir, "dist", path), "utf8");
    assert.match(file("robots.txt"), /^Sitemap: https:\/\/example\.com\/sitemap\.xml$/m);
    assert.match(file("sitemap.xml"), /<loc>https:\/\/example\.com\/posts\/a-new\/<\/loc>/);

    rmSync(join(dir, "src/content/posts"), { recursive: true, force: true });
    mkdirSync(join(dir, "src/content/posts"), { recursive: true });
    build(dir);
    assert.match(html(dir, "posts"), /No posts yet/);
  }));

