/**
 * Soft desktop update check: compare the running version to GitHub's latest release.
 * Desktop-only callers; this module does not gate on `isMacDesktop` itself.
 */

export const GITHUB_RELEASES_REPO = "Blaise1030/orso";

const CACHE_KEY = "orso.desktopUpdate.cache";
const DISMISS_KEY = "orso.desktopUpdate.dismissed";
const CACHE_TTL_MS = 24 * 60 * 60 * 1000;

export type MacDmgArch = "aarch64-apple-darwin" | "x86_64-apple-darwin";

export interface DesktopUpdateInfo {
  /** Latest release tag without a leading `v`. */
  version: string;
  downloadUrl: string;
}

interface CacheBlob {
  fetchedAt: number;
  version: string;
}

export function stripV(version: string): string {
  return version.trim().replace(/^v/i, "");
}

/** True when `latest` is a higher semver than `current` (pre-release / junk → false). */
export function isNewer(latest: string, current: string): boolean {
  const a = parseSemver(stripV(latest));
  const b = parseSemver(stripV(current));
  if (!a || !b) return false;
  for (let i = 0; i < 3; i++) {
    if (a[i] > b[i]) return true;
    if (a[i] < b[i]) return false;
  }
  return false;
}

function parseSemver(raw: string): [number, number, number] | null {
  const m = /^(\d+)\.(\d+)\.(\d+)(?:[-+].*)?$/.exec(raw);
  if (!m) return null;
  return [Number(m[1]), Number(m[2]), Number(m[3])];
}

export function dmgUrl(arch: MacDmgArch): string {
  return `https://github.com/${GITHUB_RELEASES_REPO}/releases/latest/download/orso-${arch}.dmg`;
}

export function releasesPageUrl(): string {
  return `https://github.com/${GITHUB_RELEASES_REPO}/releases/latest`;
}

/** Best-effort Mac arch for the DMG asset name. */
export function detectMacArch(ua = navigator.userAgent): MacDmgArch | null {
  if (/Mac OS X|Macintosh/i.test(ua) && /ARM|aarch64|Apple Silicon/i.test(ua)) {
    return "aarch64-apple-darwin";
  }
  // Apple Silicon browsers often still report Intel in UA; prefer aarch64 when platform says so.
  const platform = (navigator as Navigator & { userAgentData?: { platform?: string } }).userAgentData
    ?.platform;
  if (platform === "macOS" || /Mac OS X|Macintosh/i.test(ua)) {
    // Chromium on Apple Silicon: `navigator.userAgentData.getHighEntropyValues` is async; sync
    // heuristic — assume aarch64 on modern Macs unless clearly Intel.
    if (/Intel/i.test(ua) && !/ARM|aarch64/i.test(ua)) return "x86_64-apple-darwin";
    return "aarch64-apple-darwin";
  }
  return null;
}

export function downloadUrlForArch(arch: MacDmgArch | null): string {
  return arch ? dmgUrl(arch) : releasesPageUrl();
}

function readCache(storage: Storage): CacheBlob | null {
  try {
    const raw = storage.getItem(CACHE_KEY);
    if (!raw) return null;
    const parsed = JSON.parse(raw) as CacheBlob;
    if (typeof parsed.fetchedAt !== "number" || typeof parsed.version !== "string") return null;
    return parsed;
  } catch {
    return null;
  }
}

function writeCache(storage: Storage, blob: CacheBlob) {
  storage.setItem(CACHE_KEY, JSON.stringify(blob));
}

export function dismissUpdate(version: string, storage: Storage = localStorage) {
  storage.setItem(DISMISS_KEY, stripV(version));
}

export function dismissedVersion(storage: Storage = localStorage): string | null {
  return storage.getItem(DISMISS_KEY);
}

export async function fetchLatestTag(
  fetchImpl: typeof fetch = fetch,
): Promise<string | null> {
  try {
    const res = await fetchImpl(
      `https://api.github.com/repos/${GITHUB_RELEASES_REPO}/releases/latest`,
      { headers: { Accept: "application/vnd.github+json" } },
    );
    if (!res.ok) return null;
    const body = (await res.json()) as { tag_name?: unknown };
    if (typeof body.tag_name !== "string" || !body.tag_name.trim()) return null;
    return stripV(body.tag_name);
  } catch {
    return null;
  }
}

/**
 * Returns update info when `latest` is newer than `current` and not dismissed.
 * Uses a 24h cache of the latest tag.
 */
export async function checkForDesktopUpdate(
  currentVersion: string,
  opts: {
    fetch?: typeof fetch;
    now?: number;
    storage?: Storage;
    arch?: MacDmgArch | null;
  } = {},
): Promise<DesktopUpdateInfo | null> {
  const storage = opts.storage ?? localStorage;
  const now = opts.now ?? Date.now();
  const fetchImpl = opts.fetch ?? fetch;
  const arch = opts.arch === undefined ? detectMacArch() : opts.arch;

  let latest: string | null = null;
  const cached = readCache(storage);
  if (cached && now - cached.fetchedAt < CACHE_TTL_MS) {
    latest = cached.version;
  } else {
    latest = await fetchLatestTag(fetchImpl);
    if (latest) writeCache(storage, { fetchedAt: now, version: latest });
  }
  if (!latest) return null;
  if (!isNewer(latest, currentVersion)) return null;
  if (dismissedVersion(storage) === stripV(latest)) return null;
  return { version: latest, downloadUrl: downloadUrlForArch(arch) };
}

// @vitest-environment happy-dom
import { afterEach, describe, expect, it, vi } from "vitest";
import {
  checkForDesktopUpdate,
  detectMacArch,
  dismissUpdate,
  dmgUrl,
  isNewer,
  stripV,
} from "./desktopUpdateCheck";

function memoryStorage(): Storage {
  const map = new Map<string, string>();
  return {
    get length() {
      return map.size;
    },
    clear: () => map.clear(),
    getItem: (k) => map.get(k) ?? null,
    setItem: (k, v) => void map.set(k, String(v)),
    removeItem: (k) => void map.delete(k),
    key: (i) => [...map.keys()][i] ?? null,
  };
}

afterEach(() => {
  vi.unstubAllGlobals();
});

describe("isNewer", () => {
  it("compares semver and ignores a leading v", () => {
    expect(isNewer("0.1.13", "0.1.12")).toBe(true);
    expect(isNewer("v0.2.0", "0.1.99")).toBe(true);
    expect(isNewer("0.1.12", "0.1.12")).toBe(false);
    expect(isNewer("0.1.11", "0.1.12")).toBe(false);
    expect(isNewer("not-a-version", "0.1.12")).toBe(false);
  });
});

describe("detectMacArch / dmgUrl", () => {
  it("maps Intel UA to x64 DMG and others on Mac to aarch64", () => {
    expect(detectMacArch("Mozilla/5.0 (Macintosh; Intel Mac OS X 10_15_7)")).toBe(
      "x86_64-apple-darwin",
    );
    expect(detectMacArch("Mozilla/5.0 (Macintosh; ARM Mac OS X 14_0)")).toBe("aarch64-apple-darwin");
    expect(dmgUrl("aarch64-apple-darwin")).toContain("orso-aarch64-apple-darwin.dmg");
  });
});

describe("checkForDesktopUpdate", () => {
  it("returns download info when latest is newer", async () => {
    const storage = memoryStorage();
    const fetchImpl = vi.fn(async () =>
      Response.json({ tag_name: "v0.2.0" }),
    ) as unknown as typeof fetch;
    const info = await checkForDesktopUpdate("0.1.12", {
      fetch: fetchImpl,
      storage,
      arch: "aarch64-apple-darwin",
      now: 1_000,
    });
    expect(info).toEqual({
      version: "0.2.0",
      downloadUrl: dmgUrl("aarch64-apple-darwin"),
    });
    expect(fetchImpl).toHaveBeenCalledTimes(1);
  });

  it("uses the 24h cache and respects dismiss until a newer tag", async () => {
    const storage = memoryStorage();
    const fetchImpl = vi.fn(async () =>
      Response.json({ tag_name: "v0.2.0" }),
    ) as unknown as typeof fetch;
    await checkForDesktopUpdate("0.1.0", {
      fetch: fetchImpl,
      storage,
      arch: null,
      now: 1_000,
    });
    dismissUpdate("0.2.0", storage);
    expect(
      await checkForDesktopUpdate("0.1.0", {
        fetch: fetchImpl,
        storage,
        arch: null,
        now: 1_000 + 60_000,
      }),
    ).toBeNull();
    expect(fetchImpl).toHaveBeenCalledTimes(1);

    const fetchNewer = vi.fn(async () =>
      Response.json({ tag_name: "v0.3.0" }),
    ) as unknown as typeof fetch;
    const next = await checkForDesktopUpdate("0.1.0", {
      fetch: fetchNewer,
      storage,
      arch: null,
      now: 1_000 + 25 * 60 * 60 * 1000,
    });
    expect(next?.version).toBe("0.3.0");
    expect(stripV("v0.3.0")).toBe("0.3.0");
  });

  it("returns null when fetch fails", async () => {
    const storage = memoryStorage();
    const fetchImpl = vi.fn(async () => {
      throw new Error("offline");
    }) as unknown as typeof fetch;
    expect(
      await checkForDesktopUpdate("0.1.0", { fetch: fetchImpl, storage, now: 1 }),
    ).toBeNull();
  });
});

import { ref } from "vue";
import {
  checkForDesktopUpdate,
  dismissUpdate,
  type DesktopUpdateInfo,
} from "./desktopUpdateCheck";
import { isMacDesktop } from "@/lib/desktop";

/** Shared soft-update result for the toast and About settings. */
export const desktopUpdate = ref<DesktopUpdateInfo | null>(null);

let started = false;

/** Kick off a background check once per app load on macOS desktop. */
export function startDesktopUpdateCheck(currentVersion: string) {
  if (!isMacDesktop() || started) return;
  started = true;
  void checkForDesktopUpdate(currentVersion).then((info) => {
    desktopUpdate.value = info;
  });
}

export function dismissDesktopUpdate() {
  const current = desktopUpdate.value;
  if (!current) return;
  dismissUpdate(current.version);
  desktopUpdate.value = null;
}

/** Test helper. */
export function resetDesktopUpdateStore() {
  desktopUpdate.value = null;
  started = false;
}

// @vitest-environment happy-dom
import { afterEach, describe, expect, it, vi } from "vitest";
import { mount } from "@vue/test-utils";
import UpdateNotice from "./UpdateNotice.vue";
import { desktopUpdate, resetDesktopUpdateStore } from "./desktopUpdateStore";

afterEach(() => {
  resetDesktopUpdateStore();
});

describe("UpdateNotice", () => {
  it("stays hidden until an update is available", async () => {
    const w = mount(UpdateNotice);
    expect(w.find("[data-testid='update-notice']").exists()).toBe(false);

    desktopUpdate.value = {
      version: "1.2.3",
      downloadUrl: "https://github.com/Blaise1030/orso/releases/latest/download/orso-aarch64-apple-darwin.dmg",
    };
    await w.vm.$nextTick();
    const notice = w.find("[data-testid='update-notice']");
    expect(notice.exists()).toBe(true);
    expect(notice.text()).toContain("Update available");
    expect(notice.text()).toContain("1.2.3");
    w.unmount();
  });

  it("opens the download URL", async () => {
    const openUrl = vi.fn();
    desktopUpdate.value = {
      version: "1.2.3",
      downloadUrl: "https://example.com/orso.dmg",
    };
    const w = mount(UpdateNotice, { props: { openUrl } });
    await w.find("[data-testid='update-download']").trigger("click");
    expect(openUrl).toHaveBeenCalledWith("https://example.com/orso.dmg");
    w.unmount();
  });

  it("can be dismissed", async () => {
    desktopUpdate.value = {
      version: "1.2.3",
      downloadUrl: "https://example.com/orso.dmg",
    };
    const w = mount(UpdateNotice);
    await w.find("[data-testid='update-dismiss']").trigger("click");
    expect(w.find("[data-testid='update-notice']").exists()).toBe(false);
    expect(desktopUpdate.value).toBeNull();
    w.unmount();
  });
});

