    if (projectId.value === id && active.value?.branch === branch) {
      stopStatusPolling();
      status.value = pr;
      if (pr) {
        prUrl.value = pr.url;
        pollTimer = setTimeout(() => void refreshStatus(), STATUS_POLL_MS);
      }
    }
  } catch (e) {
